/* ---------- Data picker ---------- */
/* maps data from earlier steps into a step's fields. Each field holds tokens, the step and then its field, and a + that opens
   the picker: only what earlier steps hand on, grouped by step under each step's tile in its kind's colour, each field with
   its type as a coloured chip and a sample value. Search filters it, the arrows move through it and Enter puts the field in */
.fpk{position:relative;width:100%;max-width:var(--dm-field-w);container:fpk/inline-size;margin-inline:auto;display:flex;flex-direction:column;gap:var(--dm-s-3);text-align:left}
/* in its own container (owner, 16 Nov): the field width inside, the padding around it */
.fpk.panel{max-width:calc(var(--dm-field-w) + 2 * var(--dm-s-4));padding:var(--dm-s-4)}
.fpk-hd{display:flex;align-items:center;gap:var(--dm-s-2);font-size:13px}
.fpk-hd b{font-weight:500}
.fpk-hd .muted{margin-left:auto;font-size:12px}
.fpk-ti{width:18px;height:18px;flex:none;display:grid;place-items:center;border-radius:calc(5px * var(--dm-rk-s,var(--dm-rk)));background:var(--dm-fpk-kb,var(--dm-chip));color:var(--dm-fpk-kf,var(--dm-fg2))}
.fpk-ti .i{width:11px;height:11px}
.fpk-hd .fpk-ti{width:24px;height:24px;border-radius:calc(7px * var(--dm-rk-m,var(--dm-rk)))}
.fpk-hd .fpk-ti .i{width:12px;height:12px}
:is(.fpk-ti,.fpk-tok)[data-k="trigger"]{--dm-fpk-kb:var(--dm-pp-bg);--dm-fpk-kf:var(--dm-pp)}
:is(.fpk-ti,.fpk-tok)[data-k="ai"]{--dm-fpk-kb:var(--dm-pl-bg);--dm-fpk-kf:var(--dm-pl)}
:is(.fpk-ti,.fpk-tok)[data-k="tool"]{--dm-fpk-kb:var(--dm-pt-bg);--dm-fpk-kf:var(--dm-pt)}
.fpk-ti:is([data-k="app"],[data-k="output"]),.fpk-tok:is([data-k="app"],[data-k="output"]){--dm-fpk-kb:var(--dm-pb-bg);--dm-fpk-kf:var(--dm-pb)}
:is(.fpk-ti,.fpk-tok)[data-k="branch"]{--dm-fpk-kb:var(--dm-py-bg);--dm-fpk-kf:var(--dm-py)}
:is(.fpk-ti,.fpk-tok)[data-k="wait"]{--dm-fpk-kb:var(--dm-pk-bg);--dm-fpk-kf:var(--dm-pk)}
:is(.fpk-ti,.fpk-tok)[data-k="approval"]{--dm-fpk-kb:var(--dm-pm-bg);--dm-fpk-kf:var(--dm-pm)}
.fpk-f{display:flex;flex-direction:column;gap:6px}
.fpk-l{font-size:12.5px;color:var(--dm-muted)}
.fpk-box{display:flex;flex-wrap:wrap;align-items:flex-start;gap:6px;min-height:var(--dm-field-h);padding:6px 6px 6px var(--dm-s-2);border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.fpk-box{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.fpk-box:has([aria-expanded="true"]){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
/* the tokens wrap among themselves, so the + stays on the field's first line at its right end */
.fpk-toks{flex:1 1 0;min-width:0;min-height:26px;display:flex;flex-wrap:wrap;align-items:flex-start;align-content:center;gap:6px}
.fpk-ph{font-size:13px;line-height:26px;color:var(--dm-muted)}
.fpk-tok{display:inline-flex;align-items:center;gap:5px;max-width:100%;min-width:0;height:26px;padding:0 2px 0 4px;border-radius:var(--dm-r-sm);background:var(--dm-chip);font-size:12px;color:var(--dm-fg);white-space:nowrap}
.fpk-tok .s{min-width:0;max-width:120px;color:var(--dm-muted);overflow:hidden;text-overflow:ellipsis}
.fpk-tok .sep{color:var(--dm-muted)}
/* a token keeps its step's colour once it is in (owner, 22 Nov: grey tokens looked disabled): the core tag colours, one per
   kind of step, as its tile in the picker shows it, its words in the tag's text colour on the tag's tint (4.5:1), its icon
   bare on that tint and its remove in the same colour. Blueprint keeps its outlined tokens */
.fpk-tok[data-k]{background:var(--dm-fpk-kb);color:var(--dm-fpk-kf)}
.fpk-tok[data-k] :is(.s,.sep,.fpk-x){color:inherit}
.fpk-tok[data-k] .sep{opacity:.6}
.fpk-tok[data-k] .fpk-ti{background:none;box-shadow:none;color:inherit}
@media (hover:hover) and (pointer:fine){.fpk-tok[data-k] .fpk-x:hover{color:inherit}}
.fpk-tok .f{flex:none;max-width:100%;font-weight:500;overflow:hidden;text-overflow:ellipsis}
.fpk-tok.new{animation:popin .5s var(--dm-ease) backwards}
.fpk-tok.out{animation:leave .3s var(--dm-ease) both}
.fpk-x{width:20px;height:20px;flex:none;display:grid;place-items:center;border-radius:calc(5px * var(--dm-rk-s,var(--dm-rk)));color:var(--dm-muted);transition:background var(--dm-t-fast),color var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.fpk-x:hover{background:color-mix(in srgb,currentColor 12%,transparent);color:var(--dm-fg)}}
.fpk-add{width:26px;height:26px;flex:none;display:grid;place-items:center;margin-left:auto;border-radius:var(--dm-r-sm);color:var(--dm-muted);transition:background var(--dm-t-fast),color var(--dm-t-fast)}
/* the + under the pointer takes a quiet fill; open, its field's edge steps up instead (no fill), so it stays where the others are */
@media (hover:hover) and (pointer:fine){.fpk-add:hover{background:var(--dm-row);color:var(--dm-fg)}}
.fpk-add[aria-expanded="true"]{color:var(--dm-fg)}
/* the picker, on one set of columns (owner, 18 Nov): each step's tile and the search's glass centred in one column 16px in, the
   step names, the fields and the search's words on the next, the samples and step numbers ending 16px from the right edge,
   and the footnote on the content's left edge */
.fpk-pop.pop{width:min(320px,100cqi,calc(100vw - 32px));padding:var(--dm-s-2);display:flex;flex-direction:column;gap:var(--dm-s-1)}
.fpk-q{display:flex;align-items:center;gap:10px;height:36px;padding:0 10px;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);color:var(--dm-muted);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.fpk-q{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.fpk-q:focus-within{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.fpk-q input{flex:1;min-width:0;height:100%;padding:0;border:0;outline:0;background:none;font:inherit;font-size:13px;color:var(--dm-fg)}
.fpk-q input::placeholder{color:var(--dm-muted)}
.fpk-ls{max-height:252px;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:var(--dm-rail) transparent}
.fpk-g{display:flex;align-items:center;gap:var(--dm-s-2);padding:var(--dm-s-2) var(--dm-s-2) var(--dm-s-1);font-size:12px;color:var(--dm-muted)}
.fpk-g b{min-width:0;font-weight:500;color:var(--dm-fg2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fpk-g .n{margin-left:auto;flex:none}
.fpk-o{display:grid;grid-template-columns:auto auto minmax(0,1fr);align-items:center;gap:var(--dm-s-2);height:32px;padding:0 var(--dm-s-2) 0 34px;border-radius:var(--dm-r-sm);font-size:13px;cursor:pointer;user-select:none}
.fpk-o.on{background:var(--dm-row)}
.fpk-o .k{white-space:nowrap}
.fpk-o .k mark{background:none;color:inherit;font-weight:500;text-decoration:underline;text-decoration-color:var(--dm-faint);text-underline-offset:2px}
.fpk-o .ex{min-width:0;text-align:right;font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fpk-o .tag{font-weight:500}
.fpk-e{margin:0;padding:var(--dm-s-4) var(--dm-s-2);font-size:12.5px;color:var(--dm-muted)}
.fpk-ft{display:flex;align-items:center;gap:var(--dm-s-2);margin:0;padding:var(--dm-s-2) var(--dm-s-2) 0;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:12px;line-height:18px;color:var(--dm-muted)}
.fpk-ft .kh{display:flex;gap:var(--dm-s-1);flex:none}
.fpk-ft span:first-child{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fpk-live{position:absolute;left:0;top:0;width:1px;height:1px;margin:0;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
@media (prefers-reduced-motion:reduce){.fpk-tok.new,.fpk-tok.out{animation:none!important}}
@container fpk (max-width:300px){.fpk-ft .kh{display:none}}
:root:not([data-style="soft"],[data-style="clean"]) .fpk-ti:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-fpk-kf,var(--dm-rail)) 30%,transparent)}
:root:not([data-style="soft"],[data-style="clean"]) .fpk-tok:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 60%,transparent)}
:root:not([data-style="soft"],[data-style="clean"]) .fpk-tok[data-k]:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){color:var(--dm-fg)}
:root:not([data-style="soft"],[data-style="clean"]) .fpk-tok[data-k] :is(.s,.sep,.fpk-x):not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){color:var(--dm-muted)}
:root:not([data-style="soft"],[data-style="clean"]) .fpk-tok[data-k] .sep:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){opacity:1}
:root:not([data-style="soft"],[data-style="clean"]) .fpk-tok[data-k] .fpk-ti:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){background:var(--dm-fpk-kb);color:var(--dm-fpk-kf);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-fpk-kf,var(--dm-rail)) 30%,transparent)}
/* Clean: the steps' tiles are one neutral grey with a hairline, as Trace view's marks are (the data types keep their colours);
   a token is a chip, so it is a pill with a round mark and a round remove, and the + is a circle. The picker is a 22px card with
   its rows' fills concentric with it (14px, 8px in), and its footnote is an off-white foot strip, edge to edge, 16px in */
/* (owner, 22 Nov) the steps in the picker keep their kind's colour, so a token added from one wears the same colour in its
   field; only the step being edited, in the head, is the neutral tile, its icon in the text colour (white in dark mode, not
   grey), as the + and the search's glass are. Its states read apart: empty, a muted line; adding, the field's edge one step
   stronger and its + on Clean's selected fill while the picker is open; added, the coloured token */
:root[data-style="clean"] .fpk-hd .fpk-ti,:root [data-style="clean"] .fpk-hd .fpk-ti,:root [data-style="clean"].fpk-hd .fpk-ti{color:var(--dm-fg);background:var(--dm-chip);box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] :is(.fpk-add,.fpk-q>.i,.fpk-q>svg),:root [data-style="clean"] :is(.fpk-add,.fpk-q>.i,.fpk-q>svg),:root [data-style="clean"]:is(.fpk-add,.fpk-q>.i,.fpk-q>svg){color:var(--dm-fg2)}
:root[data-style="clean"] .fpk-add[aria-expanded="true"],:root [data-style="clean"] .fpk-add[aria-expanded="true"],:root [data-style="clean"].fpk-add[aria-expanded="true"]{background:var(--dm-row-on);color:var(--dm-fg)}
@media (prefers-color-scheme:dark){:root[data-style="clean"]:not([data-theme="light"]) :is(.fpk-add,.fpk-q>.i,.fpk-q>svg),:root:not([data-theme="light"]) [data-style="clean"] :is(.fpk-add,.fpk-q>.i,.fpk-q>svg),:root:not([data-theme="light"]) [data-style="clean"]:is(.fpk-add,.fpk-q>.i,.fpk-q>svg){color:var(--dm-fg)}}
:root[data-style="clean"][data-theme="dark"] :is(.fpk-add,.fpk-q>.i,.fpk-q>svg),:root[data-theme="dark"] [data-style="clean"] :is(.fpk-add,.fpk-q>.i,.fpk-q>svg),:root[data-theme="dark"] [data-style="clean"]:is(.fpk-add,.fpk-q>.i,.fpk-q>svg){color:var(--dm-fg)}
:root[data-style="clean"] .fpk-tok .fpk-ti,:root [data-style="clean"] .fpk-tok .fpk-ti,:root [data-style="clean"].fpk-tok .fpk-ti{border-radius:50%}
:root[data-style="clean"] .fpk-tok,:root [data-style="clean"] .fpk-tok,:root [data-style="clean"].fpk-tok{padding:0 3px 0 4px;border-radius:var(--dm-r-pill)}
:root[data-style="clean"] :is(.fpk-x,.fpk-add),:root [data-style="clean"] :is(.fpk-x,.fpk-add),:root [data-style="clean"]:is(.fpk-x,.fpk-add){border-radius:50%;transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .fpk-x:hover,:root [data-style="clean"] .fpk-x:hover,:root [data-style="clean"].fpk-x:hover{background:color-mix(in srgb,currentColor 12%,transparent)}}
:root[data-style="clean"] .fpk-box,:root [data-style="clean"] .fpk-box,:root [data-style="clean"].fpk-box{transition:box-shadow var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .fpk-pop.pop,:root [data-style="clean"] .fpk-pop.pop,:root [data-style="clean"].fpk-pop.pop{border-radius:var(--dm-r-card);padding-bottom:0}
:root[data-style="clean"] .fpk-o,:root [data-style="clean"] .fpk-o,:root [data-style="clean"].fpk-o{border-radius:calc(var(--dm-r-card) - 8px);transition:background-color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .fpk-ft,:root [data-style="clean"] .fpk-ft,:root [data-style="clean"].fpk-ft{margin:var(--dm-s-1) calc(-1 * var(--dm-s-2)) 0;padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-top-color:var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .fpk-tok.new,:root [data-style="clean"] .fpk-tok.new,:root [data-style="clean"].fpk-tok.new{animation:clpiece var(--dm-t-slow) var(--dm-ease) backwards}

DM.def('data-picker', (r, c) => {
  r.innerHTML = r.innerHTML.replace(/\{([\w-]+)(?:\.(xs))?\}/g, (m, k, z) => I(k, z || 's'));
  const uid = 'fpk' + Math.random().toString(36).slice(2, 7);
  const box = $('.fpk', r), pop = $('.fpk-pop', r), q = $('.fpk-q input', r), ls = $('.fpk-ls', r), live = $('.fpk-live', r);
  // each data type has its colour: text blue, numbers green, lists orange, objects pink, yes or no yellow, dates teal
  const TY = { text:'b', number:'m', list:'p', object:'k', bool:'y', date:'t' };
  // the steps before Send the reply, in their order, and what each hands on: [field, type, sample]
  const S = [
    { id:'form', t:'Demo request form', k:'trigger', ic:'file-text', f:[['name', 'text', 'Priya Shah'], ['email', 'text', 'priya@corvid.io'], ['company', 'text', 'Corvid Analytics'], ['seats', 'number', '240'], ['sent_at', 'date', 'Nov 8, 10:41']] },
    { id:'lookup', t:'Company lookup', k:'tool', ic:'globe', f:[['employees', 'number', '420'], ['industry', 'text', 'Analytics software'], ['verified', 'bool', 'true']] },
    { id:'research', t:'Research and score', k:'ai', ic:'spark', f:[['score', 'number', '84'], ['tier', 'text', 'Enterprise'], ['reasons', 'list', '3 reasons'], ['company', 'object', '{ 5 fields }']] },
    { id:'reply', t:'Draft a reply', k:'ai', ic:'edit', f:[['subject', 'text', 'Your demo with Fernhill'], ['body', 'text', 'Hi Priya, thanks for writing']] }
  ];
  const F = { to:{ l:'To', v:['form.email'] }, subject:{ l:'Subject', v:['reply.subject', 'form.company'] }, body:{ l:'Body', v:['reply.body'] } };
  let target = null, items = [], hi = 0;
  ls.id = uid + '-ls'; q.setAttribute('aria-controls', ls.id);
  const say = t => { live.textContent = ''; c.later(40, () => { live.textContent = t; }); };
  const of = ref => { const [s, f] = ref.split('.'); return { st:S.find(x => x.id === s), f }; };
  const tokHTML = ref => { const { st, f } = of(ref);
    return `<span class="fpk-tok" data-ref="${ref}" data-k="${st.k}"><span class="fpk-ti" data-k="${st.k}" aria-hidden="true">${I(st.ic, 'xs')}</span><span class="s">${st.t}</span><span class="sep" aria-hidden="true">›</span><span class="f">${f}</span><button class="fpk-x" aria-label="Remove ${f} from ${st.t}" data-tip="Remove">${I('x', 'xs')}</button></span>`; };
  const addB = k => `<button class="fpk-add" data-f="${k}" data-pop=".fpk-pop" data-pop-pos="down" data-pop-align="end" aria-haspopup="dialog" aria-expanded="false" aria-label="Insert data into ${F[k].l}" data-tip="Insert data">${I('plus', 's')}</button>`;
  const paintField = k => { $(`.fpk-f[data-f="${k}"] .fpk-box`, r).innerHTML = '<span class="fpk-toks">' + (F[k].v.length ? F[k].v.map(tokHTML).join('') : '<span class="fpk-ph">Pick data from an earlier step</span>') + '</span>' + addB(k); };
  Object.keys(F).forEach(paintField);
  const mark = (t, v) => { const i = v ? t.toLowerCase().indexOf(v) : -1; return i < 0 ? t : t.slice(0, i) + '<mark>' + t.slice(i, i + v.length) + '</mark>' + t.slice(i + v.length); };
  function paint(){
    const v = q.value.trim().toLowerCase(); let h = '', n = 0; items = [];
    S.forEach((st, si) => {
      const fs = st.f.filter(([f]) => !v || f.toLowerCase().includes(v) || st.t.toLowerCase().includes(v)); if (!fs.length) return;
      h += `<div role="group" aria-labelledby="${uid}-g${si}"><div class="fpk-g" id="${uid}-g${si}"><span class="fpk-ti" data-k="${st.k}" aria-hidden="true">${I(st.ic, 'xs')}</span><b>${st.t}</b><span class="n">Step ${si + 1}</span></div>`
        + fs.map(([f, t, ex]) => { const ref = st.id + '.' + f, i = n++; items.push(ref);
          return `<div class="fpk-o" role="option" id="${uid}-o${i}" aria-selected="false" data-i="${i}" aria-label="${f}, ${t}, from ${st.t}"><span class="k">${mark(f, v)}</span><span class="tag ${TY[t]}">${t}</span><span class="ex">${ex}</span></div>`; }).join('') + '</div>';
    });
    ls.innerHTML = h || `<p class="fpk-e">No field matches “${q.value.trim().replace(/</g, '&lt;')}”</p>`;
    hi = 0; move(0);
  }
  function move(d){
    const os = $$('.fpk-o', ls); if (!os.length){ q.removeAttribute('aria-activedescendant'); return; }
    hi = (hi + d + os.length) % os.length;
    os.forEach((o, i) => { o.classList.toggle('on', i === hi); o.setAttribute('aria-selected', String(i === hi)); });
    q.setAttribute('aria-activedescendant', os[hi].id); os[hi].scrollIntoView({ block:'nearest' });
  }
  function pick(i){
    const ref = items[i]; if (!ref || !target) return; const k = target, { st, f } = of(ref);
    closePops();
    if (F[k].v.includes(ref)){ say(`${F[k].l} already has ${f} from ${st.t}`); return; }
    F[k].v.push(ref);
    const toks = $(`.fpk-f[data-f="${k}"] .fpk-toks`, r), ph = $('.fpk-ph', toks); if (ph) ph.remove();
    toks.insertAdjacentHTML('beforeend', tokHTML(ref)); if (!REDUCE) toks.lastElementChild.classList.add('new');
    say(`Added ${f} from ${st.t} to ${F[k].l}`);
  }
  function remove(tk, mine){
    const k = tk.closest('.fpk-f').dataset.f, ref = tk.dataset.ref, { st, f } = of(ref), toks = tk.parentElement, add = $('.fpk-add', tk.closest('.fpk-box'));
    F[k].v = F[k].v.filter(x => x !== ref);
    tk.classList.add('out'); tk.inert = true;
    setTimeout(() => { tk.remove(); if (!F[k].v.length) toks.insertAdjacentHTML('beforeend', '<span class="fpk-ph">Pick data from an earlier step</span>'); }, REDUCE ? 0 : 280);
    if (mine) add.focus({ preventScroll:true });
    say(`Removed ${f} from ${st.t}`);
  }
  // the picker opens from a field's +, on that field's data; a click puts the focus in its search
  c.on(r, 'click', e => {
    const b = e.target.closest('button');
    if (b && b.matches('.fpk-add')){ target = b.dataset.f; pop.setAttribute('aria-label', `Pick data for ${F[target].l}`); q.value = ''; paint(); if (e.isTrusted) setTimeout(() => { if (pop.classList.contains('open')) q.focus({ preventScroll:true }); }, 30); return; }
    if (b && b.matches('.fpk-x')){ remove(b.closest('.fpk-tok'), e.isTrusted); return; }
    const o = e.target.closest('.fpk-o'); if (o) pick(+o.dataset.i);
  });
  c.on(ls, 'pointermove', e => { const o = e.target.closest('.fpk-o'); if (o && +o.dataset.i !== hi){ hi = +o.dataset.i; move(0); } });
  c.on(q, 'input', paint);
  // in the search the arrows move through the fields and wrap, Enter puts the one picked in, Escape closes (the core)
  c.on(q, 'keydown', e => { if (e.key === 'ArrowDown' || e.key === 'ArrowUp'){ e.preventDefault(); move(e.key === 'ArrowDown' ? 1 : -1); } else if (e.key === 'Enter'){ e.preventDefault(); pick(hi); } });
  // the fields sit centred, and glide up as the picker opens under one of them; the picker is watched too, so when a search
  // shortens its list the fields and the list settle centred again (they sat high by the rows it lost)
  const centred = centre(c, box, () => pop.classList.contains('open') ? Math.max(box.offsetHeight, pop.offsetTop + pop.offsetHeight) : box.offsetHeight, [pop]);
  const mo = new MutationObserver(() => { if (pop.classList.contains('open')) centred(); else c.later(REDUCE ? 0 : 180, centred); });
